tmnxSvcTopoChgSdpBindMajorState = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 5, 0, 14)).setObjects(("TIMETRA-SERV-MIB", "custId"), ("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SDP-MIB", "sdpBindId"), ("TIMETRA-SDP-MIB", "sdpBindTlsStpPortState"), ("TIMETRA-SERV-MIB", "tmnxOldSdpBindTlsStpPortState"))
